import sys,random,json,copy,time
sys.path.insert(0,'submission');sys.path.insert(0,'tmp')
from protocol import validate
from te.session import run_case
from verify_replay_abs import verify_request
# Reuse path-generation from test_large_output function by exec prefix? It consumes random itself. We'll build edges/paths ourselves.
def make_case(seed,mode,alpha,rho):
 random.seed(seed)
 n=10
 chain=[(i,i+1) for i in range(n-1)];used=set(chain)
 cand=[(u,v) for u in range(n) for v in range(n) if u!=v and (u,v) not in used]
 random.shuffle(cand);pairs=chain+cand[:64-len(chain)];random.shuffle(pairs)
 edges=[[u,v,1] for u,v in pairs]
 adj={u:[] for u in range(n)}
 for e,(u,v) in enumerate(pairs):adj[u].append((v,e))
 def paths_for(s,t,maxp=80):
  out=[]
  def dfs(u,path,seen):
   if len(out)>=maxp:return
   if u==t:
    if path:out.append(list(path))
    return
   if len(path)>=12:return
   for v,e in adj.get(u,[]):
    if v not in seen:
     seen.add(v);path.append(e);dfs(v,path,seen);path.pop();seen.remove(v)
     if len(out)>=maxp:return
  dfs(s,[],{s});return out
 coms=[]
 for k in range(24):
  ps=paths_for(0,9);random.shuffle(ps);g=[]
  for j in range(3):g.append(ps.pop() if ps else None)
  g.append(None)
  coms.append({'source':0,'sink':9,'demand':random.choice([1,10,1000]),'paths':g})
 case={'nodes':n,'edges':edges,'commodities':coms,'workers':[list(range(24))],'quorum':1,'max_lag':12,
       'relax':alpha,'rho':rho,'mode':mode,'events':[]}
 ev=[];tid=0
 for cyc in range(48):
  ev.append({'op':'issue','id':tid,'worker':0});tid+=1
  ev.append({'op':'deliver','id':tid-1})
  ev.append({'op':'step'})
 ev += [{'op':'audit'} for _ in range(256-len(ev))]
 case['events']=ev
 return case
t0=time.time()
for trial in range(80):
 mode=random.choice(['route','admit'])
 alpha=random.choice([[1,1],[3,2],[15,8],[16,9]])
 rho=random.choice([1,8])
 c=make_case(1000+trial,mode,alpha,rho)
 req={'cases':[c]};validate(req)
 out={'cases':[run_case(c)]}
 try:verify_request(req,out)
 except Exception as e:
  print('FAIL',trial,mode,alpha,rho,e);open('tmp/max_fail.json','w').write(json.dumps(req));open('tmp/max_fail_out.json','w').write(json.dumps(out));raise
 if trial%10==0:print('trial',trial,'sec',time.time()-t0)
print('ALL MAX STRESS RANDOM OK',time.time()-t0)
